describe('Multiple Concurrent API Calls Resolution', () => {
  beforeEach(() => {
    cy.visit('/data-page');
  });

  it('should display data after multiple concurrent API calls resolve', () => {
    // Intercept the first API call
    cy.intercept('GET', '/api/data1').as('getData1');
    // Intercept the second API call
    cy.intercept('GET', '/api/data2').as('getData2');
    // Intercept the third API call
    cy.intercept('GET', '/api/data3').as('getData3');

    // Wait for the first API call to resolve
    cy.wait('@getData1');

    // Wait for the second API call to resolve
    cy.wait('@getData2');

    // Wait for the third API call to resolve
    cy.wait('@getData3');

    // Verify all data is loaded
    cy.get('[data-testid="data-item-1"]').should('be.visible');
    cy.get('[data-testid="data-item-2"]').should('be.visible');
    cy.get('[data-testid="data-item-3"]').should('be.visible');

    // Verify data is displayed
    cy.get('[data-testid="data-item-1"]').should('contain', 'Item 1');
    cy.get('[data-testid="data-item-2"]').should('contain', 'Item 2');
    cy.get('[data-testid="data-item-3"]').should('contain', 'Item 3');

    // Verify loading state is gone
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should handle API call failures and display error state', () => {
    // Intercept the first API call
    cy.intercept('GET', '/api/data1', {
      statusCode: 200,
      body: { id: 1, name: 'Item 1' }
    }).as('getData1');

    // Intercept the second API call with error
    cy.intercept('GET', '/api/data2', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('getData2');

    // Intercept the third API call
    cy.intercept('GET', '/api/data3', {
      statusCode: 200,
      body: { id: 3, name: 'Item 3' }
    }).as('getData3');

    // Wait for the first API call to resolve
    cy.wait('@getData1');

    // Wait for the second API call to fail
    cy.wait('@getData2');

    // Wait for the third API call to resolve
    cy.wait('@getData3');

    // Verify only successful data is displayed
    cy.get('[data-testid="data-item-1"]').should('be.visible');
    cy.get('[data-testid="data-item-3"]').should('be.visible');

    // Verify error state is displayed for failed data
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load data');

    // Verify loading spinner is gone
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });
});
